// ── 1. Sort all rows by Score ascending ──────────────────────────────
const rows = items.map(item => item.json);
if (rows.length === 0) {
  throw new Error('No rows extracted from the CSV - nothing to publish to Notion.');
}

rows.sort((a, b) => {
  const sa = parseFloat(a.Score), sb = parseFloat(b.Score);
  const aOk = !isNaN(sa), bOk = !isNaN(sb);
  if (aOk && bOk) return sa - sb;
  return aOk ? -1 : bOk ? 1 : 0;
});

const headers = Object.keys(rows[0]);
const tableWidth = headers.length;

// ── 2. Notion hard limits ────────────────────────────────────────────
// No block array may hold more than 100 elements, and a single request
// body must stay under 500 KB. Stay well inside both so page creation
// and every append succeed.
const MAX_ROWS_PER_TABLE = 100;          // table_row blocks per table
const MAX_REQUEST_BYTES  = 150 * 1024;   // ~150 KB of JSON per API call

function makeRow(cells, bold) {
  return {
    type: 'table_row',
    table_row: {
      cells: cells.map(cell => {
        const txt = (cell == null || String(cell) === 'nan') ? '' : String(cell).slice(0, 2000);
        return [{ type: 'text', text: { content: txt }, annotations: bold ? { bold: true } : {} }];
      })
    }
  };
}

const allRows = [
  makeRow(headers, true),
  ...rows.map(r => makeRow(headers.map(h => r[h] ?? ''), false))
];

// ── 3. Split rows into table blocks of at most 100 rows ──────────────
const tables = [];
for (let i = 0; i < allRows.length; i += MAX_ROWS_PER_TABLE) {
  tables.push({
    type: 'table',
    table: {
      table_width: tableWidth,
      has_column_header: i === 0,   // only the first table carries the header
      has_row_header: false,
      children: allRows.slice(i, i + MAX_ROWS_PER_TABLE)
    }
  });
}

// ── 4. Pack tables into requests that fit the byte budget ────────────
const batches = [];
let current = [];
let currentBytes = 0;
for (const table of tables) {
  const size = JSON.stringify(table).length;
  if (current.length > 0 && currentBytes + size > MAX_REQUEST_BYTES) {
    batches.push(current);
    current = [];
    currentBytes = 0;
  }
  current.push(table);
  currentBytes += size;
}
if (current.length > 0) batches.push(current);

// ── 5. Title date taken from the DATA, not from the container clock ──
// The Python step writes ..._ranking_YYYY-MM-DD.csv, so read the date
// from the file name (newest file wins). Only if that is unavailable do
// we fall back to "yesterday" in Singapore time (UTC+8), computed from
// UTC on purpose so the container's own timezone cannot shift it.
const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const fmt = d => `${String(d.getUTCDate()).padStart(2,'0')}-${MONTHS[d.getUTCMonth()]}-${d.getUTCFullYear()}`;

let dataDate = null;
try {
  for (const f of $('Read Results2').all()) {
    const m = String(f.json.fileName || '').match(/(\d{4})-(\d{2})-(\d{2})/);
    if (!m) continue;
    const d = new Date(`${m[1]}-${m[2]}-${m[3]}T00:00:00Z`);
    if (!dataDate || d > dataDate) dataDate = d;
  }
} catch (e) {
  // 'Read Results2' not available (e.g. single-node test run) - use fallback
}

let dateLabel;
if (dataDate) {
  dateLabel = fmt(dataDate);
} else {
  const sgt = new Date(Date.now() + 8 * 3600 * 1000);  // read with getUTC* => SGT wall clock
  sgt.setUTCDate(sgt.getUTCDate() - 1);
  dateLabel = fmt(sgt);
}

const title = `${dateLabel} Magic Formula Results (Dow30 + Nasdaq100 + SNP500)`;

// ── 6. One item per API request ──────────────────────────────────────
// Item 0 creates the page; each remaining item is appended in its own request.
return batches.map((children, i) => ({
  json: {
    title,
    dateLabel,
    chunkIndex: i,
    totalChunks: batches.length,
    tableCount: children.length,
    totalRows: allRows.length,
    children
  }
}));

