// The page was created from chunk 0 by 'Create Notion Page'.
// Emit one item per remaining chunk so the HTTP node appends them one
// request at a time, and pass through safely when there is nothing left.
const page = $input.first().json;
const chunks = $('Build Table Blocks').all();

const remaining = chunks.slice(1);
if (remaining.length === 0) {
  return [{ json: { pageId: page.id, pageUrl: page.url, chunkIndex: 0, children: [], hasBatches: false } }];
}

return remaining.map((item, i) => ({
  json: {
    pageId: page.id,
    pageUrl: page.url,
    chunkIndex: item.json.chunkIndex ?? i + 1,
    tableCount: item.json.tableCount,
    children: item.json.children,
    hasBatches: true
  }
}));
